#!/usr/bin/env python3import numpy as npimport osimport reimport argparsedef get_bus_from_atpmap(filepath, feeder):    ''' Pulls out a list of the CIM bus names from the atpmap file        Since each feeder has a custom naming scheme, this is        handled differently depending on the feeder.    '''    # Load lines into a list    lines = list()    with open(filepath, 'r') as f:        for line in f:            if line.strip() == '':                break            lines.append(re.split('\s\s+', line.strip()))    # Check for CIM bus and ATP bus    cim_idx = [i for i, l in enumerate(lines[0]) if 'CIM' in l][0]    atp_idx = [i for i, l in enumerate(lines[0]) if 'ATP' in l][0]    del lines[0] # Remove header    # Load the lines, excluding unwanted CIM buses    cim_buses = list()    atp_buses = list()    for vals in lines:        cim_bus = vals[cim_idx]        atp_bus = vals[atp_idx]        if feeder == 'IEEE13':            # IEEE13 we exclude cim bus names with alpha characters            if re.search('[a-zA-Z]', cim_bus) is None:                cim_buses.append(cim_bus)                atp_buses.append(atp_bus)        elif feeder == 'IEEE123':            if cim_bus.startswith('s') or cim_bus.endswith('_open'):                pass            else:                cim_buses.append(cim_bus)                atp_buses.append(atp_bus)        elif feeder == 'IEEE9500':            if 'hvmv' in cim_bus or cim_bus.startswith('x') or cim_bus.startswith('sx') or \                cim_bus.endswith('_cap') or cim_bus.startswith('regxfmr') or cim_bus == 'sourcebus':                pass            else:                cim_buses.append(cim_bus)                atp_buses.append(atp_bus)    return cim_buses, atp_buses    # if feeder == 'IEEE13':def get_phases_from_atp(filepath, buses, feeder):    ''' Returns a dictionary of {bus:phases} where phases is 'ABC', 'BC', 'A', etc. '''        def look_for_abc(atp_net, phase_set, idx, idx_ext=0, end_str="$VINTAGE,0"):        # Skip a few comment lines, then go until the end statement, $VINTAGE,0        while not atp_net[idx+idx_ext].startswith(end_str):            # Just having the phase letter in the line seems to be sufficient            if 'A' in atp_net[idx+idx_ext]:                phase_set = phase_set.union(set('A'))            if 'B' in atp_net[idx+idx_ext]:                phase_set = phase_set.union(set('B'))            if 'C' in atp_net[idx+idx_ext]:                phase_set = phase_set.union(set('C'))            idx_ext += 1        return phase_set            atp_net = list()    with open(filepath, 'r') as f:        for line in f:            atp_net.append(line.strip())    phase_dict = dict()    # This isn't the most efficient search. It goes line-by-line looking for    # to/from bus. Limits to lines starting with "C line"    # Restarts the search for each bus    three_phase_set = set('ABC')    for bus in buses:        # Use a set since we're only looking to see which phases are on this bus        phase_set = set('')        for i, line in enumerate(atp_net):            # Check lines first            if line.startswith("C line") or line.startswith("C OH line"):                # Added whitespace after from bus and endwith to 'to bus' so we don't                # confuse 100 for 10 (or similar)                if f'from {bus} ' in line or line.endswith(f'to {bus}'):                    phase_set = look_for_abc(atp_net, phase_set, i, idx_ext=4, end_str="$VINTAGE,0")            # Now check loads:            if line.startswith("C load"):                if f'at {bus} ' in line:                    phase_set = look_for_abc(atp_net, phase_set, i, idx_ext=3, end_str="$VINTAGE,0")            # Get the substation:            if line.startswith("C Substation"):                if line.endswith(f'at {bus}'):                    phase_set = look_for_abc(atp_net, phase_set, i, idx_ext=3, end_str="/BRANCH")            # Finally check other equipment            equip = ['Breaker', 'Fuse', 'LoadBreakSwitch']            for eq in equip:                if line.startswith(f'C {eq}'):                    if f'from {bus} ' in line or line.endswith(f'to {bus}'):                        phase_set = look_for_abc(atp_net, phase_set, i, idx_ext=1, end_str="C ==")            #            if feeder == 'IEEE9500':                if line.startswith('C SyncMachine'):                    if f'at {bus} ':                        phase_set = look_for_abc(atp_net, phase_set, i, idx_ext=2,                                                 end_str="PARAMETER")            # If we find all three phases, there's no point in checking more lines            if phase_set == three_phase_set:                break        found_phases = ''.join(sorted(phase_set))        if feeder == 'IEEE123':            # If no phases were found, exclude this from consideration            if found_phases == '':                continue        phase_dict[bus] = found_phases    return phase_dictdef make_zone_csv(phase_dict, cim_atp_dict, feeder):    header = ['zone_0','zone_adj'] # Include adjacent feeders 1, 2, and 3    zone_info = [header]    for i, bus in enumerate(phase_dict.keys()):        zline = [f'{cim_atp_dict[bus]}_{phase_dict[bus]}']        if i < 3:            zline += [f'ADJ{i+1}_ABC']        else:            zline += ['']        zone_info.append(zline)    zone_info = np.array(zone_info)    np.savetxt(f'zone_info_{feeder}_PV.csv', zone_info, fmt='%s', delimiter=',')if __name__ == '__main__':    parser = argparse.ArgumentParser()    parser.add_argument('-f', '--feeder', type=str, help='Feeder name (eg. IEEE123)',                       default='IEEE13')    args = parser.parse_args()    root = os.getcwd()    feeder = args.feeder    if feeder == 'IEEE9500':        atpmapfile = f'{feeder}.atpmap'        atpfile = f'{feeder}_net.atp'    else:        atpmapfile = f'{feeder}_PV.atpmap'        atpfile = f'{feeder}_PV_net.atp'    cim_buses, atp_buses = get_bus_from_atpmap(atpmapfile, feeder)    cim_atp_dict = dict(zip(cim_buses,atp_buses))    phase_dict = get_phases_from_atp(atpfile, cim_buses, feeder)    print(phase_dict)    make_zone_csv(phase_dict, cim_atp_dict, feeder)